/* config.h for the POSIX (Linux, later Horizon/newlib) CMake build of libsquashfs.
 * Hand-written counterpart of ../inc/config.h (the Windows one, generated by configure).
 * Only what the library sources listed in CMakeLists.txt test for. Anything optional stays
 * undefined so the compat/ fallbacks get compiled in, which also keeps newlib targets working. */
#define HAVE_INTTYPES_H 1
#define HAVE_STDINT_H 1
#define HAVE_STDIO_H 1
#define HAVE_STDLIB_H 1
#define HAVE_STRING_H 1
#define HAVE_STRINGS_H 1
#define HAVE_SYS_STAT_H 1
#define HAVE_SYS_TYPES_H 1
#define HAVE_UNISTD_H 1
#define HAVE_ZSTD_STREAM 1
/* strndup is POSIX 2008 (glibc and newlib both have it); strchrnul is a GNU extension,
 * so compat/src/strchrnul.c provides it. */
#define HAVE_STRNDUP 1

#define PACKAGE "squashfs-tools-ng"
#define PACKAGE_NAME "squashfs-tools-ng"
#define PACKAGE_STRING "squashfs-tools-ng 1.3.2"
#define PACKAGE_TARNAME "squashfs-tools-ng"
#define PACKAGE_VERSION "1.3.2"
#define STDC_HEADERS 1
#define VERSION "1.3.2"
